function initMobileDropdown() {
  const media = window.matchMedia('(max-width: 767px)');
  const groups = document.querySelectorAll('[global-dd]');

  function closeItem(item) {
    const content = item.querySelector('[global-dd-content]');
    item.classList.remove('is-open');
    gsap.to(content, {
      height: 0,
      duration: 0.4,
      ease: 'power2.inOut',
      onStart: () => {
        content.style.overflow = 'hidden';
      },
    });
  }

  function openItem(item) {
    const content = item.querySelector('[global-dd-content]');
    item.classList.add('is-open');
    gsap.set(content, {
      overflow: 'hidden',
    });

    gsap.fromTo(
      content,
      {
        height: 0,
      },
      {
        height: content.scrollHeight,
        duration: 0.4,
        ease: 'power2.inOut',
        onComplete: () => {
          content.style.height = 'auto';
        },
      }
    );
  }

  function setup() {
    groups.forEach((group) => {
      const wrappers = group.querySelectorAll('[global-dd-wrapper]');
      wrappers.forEach((wrapper, index) => {
        const toggle = wrapper.querySelector('[global-dd-toggle]');
        const content = wrapper.querySelector('[global-dd-content]');

        if (!toggle || !content) return;
        if (!media.matches) {
          gsap.killTweensOf(content);
          content.style.height = '';
          content.style.overflow = '';
          wrapper.classList.remove('is-open');
          return;
        }

        if (!wrapper.classList.contains('is-init')) {
          wrapper.classList.add('is-init');
          content.style.overflow = 'hidden';

          if (index === 0) {
            wrapper.classList.add('is-open');
            content.style.height = 'auto';
          } else {
            content.style.height = '0px';
          }
          toggle.addEventListener('click', () => {
            const isOpen = wrapper.classList.contains('is-open');

            wrappers.forEach((item) => {
              if (item !== wrapper) {
                closeItem(item);
              }
            });
            if (isOpen) {
              closeItem(wrapper);
            } else {
              openItem(wrapper);
            }
          });
        }
      });
    });
  }

  setup();
  media.addEventListener('change', setup);
}

