function initInfoCount() {
  const items = document.querySelectorAll('.global_info-item');
  const instances = [];

  const buildItem = (item) => {
    const numberEl = item.querySelector('.global_info-number');
    if (!numberEl) return null;
    if (!numberEl.hasAttribute('data-original')) {
      numberEl.setAttribute('data-original', numberEl.textContent.trim());
    }
    const original = numberEl.getAttribute('data-original');
    const digitRegex = /\d/g;
    if (!original.match(digitRegex)) return null;
    numberEl.textContent = original;
    numberEl.style.display = '';
    const cs = getComputedStyle(numberEl);
    const lineHeight = parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.2;
    const parts = [];
    let lastIdx = 0;
    original.replace(digitRegex, (match, offset) => {
      if (offset > lastIdx) parts.push({
        type: 'static',
        text: original.slice(lastIdx,
          offset)
      });
      parts.push({ type: 'digit', value: parseInt(match, 10) });
      lastIdx = offset + 1;
    });
    if (lastIdx < original.length) parts.push({ type: 'static', text: original.slice(lastIdx) });
    numberEl.innerHTML = '';
    numberEl.style.display = 'inline-flex';
    const digitWrappers = [];
    parts.forEach((part) => {
      if (part.type === 'static') {
        const span = document.createElement('span');
        span.textContent = part.text;
        span.style.whiteSpace = 'pre';
        numberEl.appendChild(span);
      } else {
        const wrap = document.createElement('span');
        wrap.style.cssText =
          `display:inline-block;height:${lineHeight}px;overflow:hidden;vertical-align:top;`;
        const inner = document.createElement('span');
        inner.style.cssText =
          `display:flex;flex-direction:column;line-height:${lineHeight}px;`;
        const totalDigits = 11;
        for (let i = 0; i < totalDigits; i++) {
          const digit = document.createElement('span');
          digit.textContent = i === 0 ? part.value : (part.value + i) % 10;
          digit.style.cssText =
            `height:${lineHeight}px;display:flex;align-items:center;justify-content:center;`;
          inner.appendChild(digit);
        }
        wrap.appendChild(inner);
        numberEl.appendChild(wrap);
        const measureSpan = document.createElement('span');
        measureSpan.textContent = part.value;
        measureSpan.style.cssText = 'visibility:hidden;position:absolute;white-space:pre;';
        numberEl.appendChild(measureSpan);
        const digitWidth = measureSpan.getBoundingClientRect().width;
        numberEl.removeChild(measureSpan);
        wrap.style.width = `${digitWidth}px`;
        digitWrappers.push({ inner });
      }
    });
    const innerEls = digitWrappers.map((d) => d.inner);
    const startY = -10 * lineHeight;
    gsap.set(innerEls, { y: startY });
    const descEl = item.querySelector('.global_info-desc');
    let descChars = null;
    let descOriginals = null;
    let descOriginalColor = null;
    let descSplit = null;
    if (descEl) {
      if (!descEl.hasAttribute('data-original')) {
        descEl.setAttribute('data-original', descEl.textContent.trim());
      }
      descEl.textContent = descEl.getAttribute('data-original');
      descOriginalColor = getComputedStyle(descEl).color;
      descSplit = new SplitText(descEl, { type: 'chars' });
      descChars = descSplit.chars;
      descOriginals = descChars.map((c) => c.textContent);
      descChars.forEach((char, idx) => {
        const w = char.getBoundingClientRect().width;
        char.style.display = 'inline-block';
        char.style.width = `${w}px`;
        char.style.textAlign = 'center';
        if (descOriginals[idx] !== ' ') char.textContent = '0';
      });
    }
    return {
      item,
      numberEl,
      innerEls,
      startY,
      descEl,
      descChars,
      descOriginals,
      descOriginalColor,
      descSplit
    };
  };

  const animateItem = (inst) => {
    const { innerEls, startY, descChars, descOriginals, descOriginalColor } = inst;
    gsap.killTweensOf(innerEls);
    gsap.set(innerEls, { y: startY });
    gsap.to(innerEls, {
      y: 0,
      duration: 0.9,
      ease: 'power3.out',
      stagger: 0.04,
      overwrite: true
    });
    if (descChars) {
      const symbols = '!@#$%^&*()_+-=[]{}|;:,.<>?/~`';
      const totalDuration = 1.6;
      const charStagger = totalDuration / descChars.length;
      descChars.forEach((char, i) => {
        gsap.killTweensOf(char);
        const settleTime = i * charStagger;
        if (descOriginals[i] === ' ') {
          char.textContent = ' ';
          return;
        }
        char.style.color = '#1E6EF3';
        const scrambleObj = { t: 0 };
        gsap.to(scrambleObj, {
          t: 1,
          duration: settleTime + 0.01,
          ease: 'none',
          onUpdate: () => {
            char.textContent = symbols[Math.floor(Math.random() * symbols.length)];
          },
          onComplete: () => {
            char.textContent = descOriginals[i];
            char.style.color = descOriginalColor;
          }
        });
      });
    }
  };

  const teardownItem = (inst) => {
    if (!inst) return;
    gsap.killTweensOf(inst.innerEls);
    if (inst.descChars) gsap.killTweensOf(inst.descChars);
    if (inst.descSplit) inst.descSplit.revert();
    if (inst.descEl && inst.descEl.hasAttribute('data-original')) {
      inst.descEl.textContent = inst.descEl.getAttribute('data-original');
    }
    if (inst.st) inst.st.kill();
  };

  const setupAll = (animateImmediately) => {
    items.forEach((item, idx) => {
      const inst = buildItem(item);
      if (!inst) return;
      instances[idx] = inst;
      if (animateImmediately) {
        const rect = item.getBoundingClientRect();
        if (rect.top < window.innerHeight * 0.85 && rect.bottom > 0) {
          animateItem(inst);
          return;
        }
      }
      inst.st = ScrollTrigger.create({
        trigger: item,
        start: 'top 85%',
        once: true,
        onEnter: () => animateItem(inst)
      });
    });
  };

  setupAll(false);

  let resizeTimer;
  let lastWidth = window.innerWidth;
  window.addEventListener('resize', () => {
    if (window.innerWidth === lastWidth) return;
    lastWidth = window.innerWidth;
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      instances.forEach((inst) => teardownItem(inst));
      instances.length = 0;
      setupAll(true);
    }, 200);
  });
}
