function initGlobalTabDropdown() {
  document.querySelectorAll('[global-tab-dd]').forEach((wrapper) => {
    const items = wrapper.querySelectorAll('[global-tab-dd-item]');

    if (!items.length) return;

    items[0].classList.add('dd-active');
    items.forEach((item) => {
      const toggle = item.querySelector('[global-tab-dd-toggle]');
      toggle?.addEventListener('click', () => {
        const isActive = item.classList.contains('dd-active');

        items.forEach((el) => {
          el.classList.remove('dd-active');
        });

        if (!isActive) {
          item.classList.add('dd-active');
        }
      });
    });
  });
}

