let currentBreakpoint = null;
let marqueeAnimation = null;

function getBreakpoint() {
  return window.innerWidth < 768 ? 'mobile' : 'desktop';
}

function cleanupNav() {
  if (marqueeAnimation) {
    marqueeAnimation.kill();
    marqueeAnimation = null;
  }

  const wrapper = document.querySelector('[data-wrapper-banner]');
  const track = wrapper?.querySelector('div[style*="display: flex"]');

  if (track && wrapper) {
    const originalBanner = track.querySelector('[data-banner]');
    if (originalBanner) {
      wrapper.insertBefore(originalBanner, track);
    }
    track.remove();
  }

  const navWrapper = document.querySelector('[nav-banner]');
  if (navWrapper) {
    gsap.set(navWrapper, { clearProps: 'display' });
  }
}

function initNav() {
  const isMobile = getBreakpoint() === 'mobile';

  if (!isMobile) {
    const navWrapper = document.querySelector('[nav-banner]');
    if (!navWrapper) return;

    const links = navWrapper.querySelectorAll('[data-nav-link]');

    links.forEach(el => {
      const underline = document.createElement('span');
      underline.style.cssText = `
        position: absolute;
        bottom: 0;
        left: 0;
        width: 100%;
        height: 1px;
        background: currentColor;
        transform: scaleX(0);
        transform-origin: left center;
      `;

      if (getComputedStyle(el).position === 'static') {
        el.style.position = 'relative';
      }

      el.appendChild(underline);

      el.addEventListener('mouseenter', () => {
        gsap.to(underline, {
          scaleX: 1,
          duration: 0.45,
          transformOrigin: 'left center'
        });
      });

      el.addEventListener('mouseleave', () => {
        gsap.to(underline, {
          scaleX: 0,
          duration: 0.45,
          transformOrigin: 'right center'
        });
      });
    });

    const navClose = navWrapper.querySelector('.icon-x');
    if (navClose) {
      const newNavClose = navClose.cloneNode(true);

      navClose.parentNode.replaceChild(newNavClose, navClose);
      newNavClose.addEventListener('click', () => {
        gsap.set(navWrapper, { display: 'none' });

      });
    }
  }
  else {
    const wrapper = document.querySelector('[data-wrapper-banner]');
    const banner = document.querySelector('[data-banner]');
    if (!wrapper || !banner) return;

    wrapper.style.willChange = 'transform';
    wrapper.style.backfaceVisibility = 'hidden';

    const track = document.createElement('div');
    track.style.display = 'flex';
    track.style.gap = '0.5em';
    track.style.willChange = 'transform';
    track.style.backfaceVisibility = 'hidden';
    track.style.perspective = '1000px';
    track.style.width = 'fit-content';

    wrapper.insertBefore(track, wrapper.firstChild);
    track.appendChild(banner);

    const gap = parseFloat(getComputedStyle(track).gap) || 0;
    const bannerWidth = banner.offsetWidth + gap;
    const wrapperWidth = wrapper.offsetWidth;
    const copies = Math.ceil(wrapperWidth / bannerWidth) + 2;

    for (let i = 0; i < copies; i++) {
      const clone = banner.cloneNode(true);
      track.appendChild(clone);
    }

    marqueeAnimation = gsap.to(track, {
      x: -bannerWidth,
      duration: 10,
      ease: 'none',
      repeat: -1,
      modifiers: {
        x: gsap.utils.unitize(x => parseFloat(x) % bannerWidth)
      }
    });

    const navWrapper = document.querySelector('[nav-banner]');

    const navClose = navWrapper.querySelector('.icon-x');
    if (navClose) {
      const newNavClose = navClose.cloneNode(true);
      const navHeight = document.querySelector('.hamburger-component');
      navClose.parentNode.replaceChild(newNavClose, navClose);
      newNavClose.addEventListener('click', () => {
        gsap.set(navWrapper, { display: 'none' });

        //gsap.set(navHeight, { top: '3em', height: 'calc(100dvh - 3em)' });

      });
    }
  }

}

function handleResizes() {
  const newBreakpoint = getBreakpoint();

  if (newBreakpoint !== currentBreakpoint) {
    cleanupNav();
    currentBreakpoint = newBreakpoint;

    initNav();
  }
}

let resizeTimeout;
window.addEventListener('resize', () => {
  clearTimeout(resizeTimeout);
  resizeTimeout = setTimeout(handleResizes, 150);
});

currentBreakpoint = getBreakpoint();
initNav();


